//! Rasterize the PDF generated by the export probe.
use anyhow::{Result, ensure};
use std::{fs, path::PathBuf};

fn main() -> Result<()> {
    let directory = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/m0");
    for (name, pages) in [("pagination", 1), ("widows-orphans", 4)] {
        let bytes = fs::read(directory.join(format!("{name}.pdf")))?;
        for page in 0..pages {
            let png = moino_preview::render_pdf_page(bytes.clone(), page)?;
            let raster = image::load_from_memory(&png)?.to_rgb8();
            ensure!(
                raster
                    .pixels()
                    .any(|pixel| pixel.0.iter().any(|channel| *channel < 240)),
                "{name} page {} rendered blank",
                page + 1,
            );
            let file = if name == "pagination" {
                "page-1.png".to_owned()
            } else {
                format!("{name}-page-{}.png", page + 1)
            };
            fs::write(directory.join(file), png)?;
        }
    }
    Ok(())
}
